'use strict';
/* GAS&GO · factura V2 descargable. Sin bibliotecas externas y disponible offline.
 * Todas las operaciones de la app son simulaciones. Ningún PDF constituye factura fiscal real.
 */
(function(){
const G='#035141',G2='#00614f',G3='#154e40',Y='#ffda2f',INK='#143c32',MUTED='#6c8078',BORDER='#dce9e2',SOFT='#f6f9f7';
// Logos integrados para que la descarga funcione incluso con index.html abierto mediante file://
const HEADER_LOGO='data:image/png;base64,';
const FOOTER_LOGO='data:image/png;base64,';
const euro=n=>Number(n||0).toLocaleString('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2})+' €';
const fmt=(n,d=2)=>Number(n||0).toLocaleString('es-ES',{minimumFractionDigits:d,maximumFractionDigits:d});
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const val=(a,d='No registrado')=>String(a??'').trim()||d;
function fields(h,f,q){
 const ev=/el[eé]ctr/i.test(h.fuel||'');
 const qty=ev?Number(h.energy||0):Number(h.liters||0);
 const unit=ev?'kWh':'L';
 const priceUnit=ev?'€/kWh':'€/L';
 const concept=ev?'Recarga eléctrica':(h.fuel||'Carburante');
 return {ev,qty,unit,concept,priceUnit,payment:val(h.payment,'No registrado'),paymentStatus:val(h.paymentStatus,'Operación simulada'),
 station:val(h.station,'Estación no registrada'),pump:val(h.pump,'No registrado'),vehicle:val(h.vehicle,'Vehículo no registrado'),plate:val(h.plate,'—'),date:val(h.date,'—'),
 issuer:val(f.issuer,'GAS&GO ESTACIONES DEMO, S.L.'),issuerNif:val(f.issuerNif,'—'),issuerAddress:val(f.issuerAddress,'—'),
 customer:val(f.customer,'—'),customerNif:val(f.customerNif,'—'),customerAddress:val(f.customerAddress,'—'),
 number:val(q.number,'SIM-2026-00001'),promo:val(h.promoLabel,'Descuento promocional')};
}
function preview(h,f,q){
 const d=fields(h,f,q);const discount=Number(q.discount||0)>0;
 return `<div class="gg-invoice-preview" aria-label="Vista previa de la factura GAS&GO">
 <div class="gg-inv-top"><img src="./logo-factura-cabecera.png" alt="Gas&Go"><div class="gg-inv-top-right"><span class="gg-inv-tag">FACTURA</span><div class="gg-inv-ref">${esc(d.number)}</div><div class="gg-inv-date">${esc(d.date)}</div></div></div>
 <div class="gg-inv-content">
  <div class="gg-inv-section">RESUMEN DEL REPOSTAJE</div>
  <div class="gg-inv-grid3"><div class="gg-inv-box"><span class="gg-inv-caption">ESTACIÓN</span><span class="gg-inv-value">${esc(d.station)}</span></div><div class="gg-inv-box"><span class="gg-inv-caption">SURTIDOR</span><span class="gg-inv-value">${esc(d.pump)}</span></div><div class="gg-inv-box"><span class="gg-inv-caption">VEHÍCULO</span><span class="gg-inv-value">${esc(d.vehicle)} / ${esc(d.plate)}</span></div></div>
  <div class="gg-inv-section">DATOS DE FACTURACIÓN</div>
  <div class="gg-inv-grid2"><div class="gg-inv-billing"><span class="gg-inv-dash"></span><div class="gg-inv-caption">EMISOR</div><strong>${esc(d.issuer)}</strong><p>CIF: ${esc(d.issuerNif)}<br>${esc(d.issuerAddress)}</p></div><div class="gg-inv-billing"><span class="gg-inv-dash"></span><div class="gg-inv-caption">CLIENTE</div><strong>${esc(d.customer)}</strong><p>DNI/NIF: ${esc(d.customerNif)}<br>${esc(d.customerAddress)}</p></div></div>
  <div class="gg-inv-section">DETALLE</div>
  <div class="gg-inv-detail"><div class="gg-inv-detail-head"><span>CONCEPTO</span><span>IMPORTE</span></div><div class="gg-inv-detail-row"><div><strong>${esc(d.concept)}</strong><small>${fmt(d.qty)} ${d.unit} × ${fmt(q.unit,3)} ${d.priceUnit}</small>${discount?`<small>${esc(d.promo)}: −${euro(q.discount)}</small>`:''}</div><strong>${euro(q.gross)}</strong></div></div>
  <div class="gg-inv-grid2"><div class="gg-inv-paycard"><div class="gg-inv-caption">PAGO</div><strong>${esc(d.payment)}</strong><p>${esc(d.paymentStatus)}</p><span class="gg-inv-paid">OPERACIÓN SIMULADA</span></div><div class="gg-inv-totalcard"><div class="gg-inv-caption" style="color:#dcefe4">RESUMEN</div><div><span>Base imponible</span><strong>${euro(q.base)}</strong></div><div><span>IVA (21 %)</span><strong>${euro(q.vat)}</strong></div><div class="gg-inv-final"><span>TOTAL</span><strong>${euro(q.total)}</strong></div></div></div>
 </div>
 <div class="gg-inv-bottom"><div><strong>DOCUMENTO FICTICIO · SIN VALIDEZ FISCAL</strong><p>Datos del emisor y operaciones exclusivamente de demostración.<br>Importes con IVA incluido. No acredita suministro ni pago real.</p></div><img src="./logo-factura-pie.png" alt="G&G"></div>
 </div>`;
}
function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('No se puede cargar el logotipo de la factura'));im.src=src;});}
function roundRect(ctx,x,y,w,h,r,fill,stroke){
 ctx.beginPath();ctx.roundRect(x,y,w,h,Math.max(0,Math.min(r,w/2,h/2)));
 if(fill){ctx.fillStyle=fill;ctx.fill()} if(stroke){ctx.lineWidth=.85;ctx.strokeStyle=stroke;ctx.stroke()}
}
function font(ctx,size=10,bold=false){ctx.font=(bold?'700 ':'400 ')+size+'px Arial, Helvetica, sans-serif'}
function text(ctx,t,x,y,size=10,color=INK,bold=false,align='left'){
 ctx.fillStyle=color;font(ctx,size,bold);ctx.textAlign=align;ctx.textBaseline='alphabetic';ctx.fillText(String(t??''),x,y);
}
function fit(ctx,t,max){let s=String(t??'');if(ctx.measureText(s).width<=max)return s;while(s.length>1&&ctx.measureText(s+'…').width>max)s=s.slice(0,-1);return s+'…'}
function fitted(ctx,t,x,y,max,size=10,color=INK,bold=false,align='left'){
 font(ctx,size,bold);text(ctx,fit(ctx,t,max),x,y,size,color,bold,align);
}
function multiline(ctx,s,x,y,width,size=9,color=MUTED,weight=false,lineH=13,maxLines=2){
 let all=[];for(const paragraph of String(s??'').split(/\n/)){let row='';for(const word of paragraph.split(/\s+/)){const next=row?row+' '+word:word;font(ctx,size,weight);if(ctx.measureText(next).width>width&&row){all.push(row);row=word;}else row=next;}all.push(row);}
 all=all.filter(Boolean);let result=all.slice(0,maxLines);
 if(all.length>maxLines&&result.length){font(ctx,size,weight);result[result.length-1]=fit(ctx,result[result.length-1]+'…',width)}
 for(let i=0;i<result.length;i++)fitted(ctx,result[i],x,y+i*lineH,width,size,color,weight);
 return result.length;
}
function drawCard(ctx,x,y,w,h){roundRect(ctx,x,y,w,h,11,SOFT,BORDER)}
function drawInvoice(ctx,h,f,q,headerLogo,footerLogo){
 const W=595,d=fields(h,f,q);
 ctx.fillStyle='#fff';ctx.fillRect(0,0,595,842);
 // Green header, accurate corporate colors with top yellow line.
 const bg=ctx.createLinearGradient(0,0,595,145);bg.addColorStop(0,G);bg.addColorStop(1,G2);
 ctx.fillStyle=bg;ctx.fillRect(0,0,W,147);ctx.fillStyle=Y;ctx.fillRect(0,0,W,6);
 if(headerLogo){const ratio=headerLogo.width/headerLogo.height;const dw=235,dh=dw/ratio;ctx.drawImage(headerLogo,35,24,dw,dh)}
 else text(ctx,'Gas&Go',39,86,42,Y,true);
 roundRect(ctx,426,30,139,34,19,Y);text(ctx,'FACTURA',495.5,53,15,G,true,'center');
 fitted(ctx,d.number,557,88,175,11,'#f6fff8',true,'right');
 fitted(ctx,d.date,557,108,180,9,'#d6f0e1',false,'right');
 // Headline and three summary boxes
 text(ctx,'RESUMEN DEL REPOSTAJE',38,171,9,MUTED,true);
 const tabs=[{x:38,k:'ESTACIÓN',v:d.station},{x:214,k:'SURTIDOR',v:d.pump},{x:390,k:'VEHÍCULO',v:d.vehicle+' / '+d.plate}];
 tabs.forEach(t=>{drawCard(ctx,t.x,185,167,62);text(ctx,t.k,t.x+12,206,8,MUTED,true);multiline(ctx,t.v,t.x+12,224,143,10,INK,true,11,2)});
 // Issuer and customer
 text(ctx,'DATOS DE FACTURACIÓN',38,279,9,MUTED,true);
 const bill=[{x:38,k:'EMISOR',name:d.issuer,nif:'CIF: '+d.issuerNif,address:d.issuerAddress},{x:305,k:'CLIENTE',name:d.customer,nif:'DNI/NIF: '+d.customerNif,address:d.customerAddress}];
 bill.forEach(t=>{
  roundRect(ctx,t.x,294,252,106,12,'#fff',BORDER);roundRect(ctx,t.x+14,307,29,5,3,Y);
  text(ctx,t.k,t.x+14,326,9,G,true);multiline(ctx,t.name,t.x+14,344,224,10,INK,true,11,2);
  fitted(ctx,t.nif,t.x+14,364,225,8,MUTED);multiline(ctx,t.address,t.x+14,380,224,8,MUTED,false,10,2);
 });
 // Detail
 text(ctx,'DETALLE',38,426,9,MUTED,true);
 roundRect(ctx,38,439,519,103,12,'#fff',BORDER);
 ctx.save();ctx.beginPath();ctx.roundRect(38,439,519,103,12);ctx.clip();const light=ctx.createLinearGradient(38,439,557,480);light.addColorStop(0,'#e9f6ee');light.addColorStop(1,'#eaf5f0');ctx.fillStyle=light;ctx.fillRect(38,439,519,28);ctx.restore();
 text(ctx,'CONCEPTO',52,457,9,G,true);text(ctx,'IMPORTE',543,457,9,G,true,'right');
 fitted(ctx,d.concept,52,488,395,11,INK,true);
 text(ctx,fmt(d.qty)+' '+d.unit+' × '+fmt(q.unit,3)+' '+d.priceUnit,52,507,9,MUTED);
 if(Number(q.discount)>0)fitted(ctx,d.promo+'  −'+euro(q.discount),52,528,410,9,G,true);
 text(ctx,euro(q.gross),542,492,11,INK,true,'right');
 // Pay / summary boxes
 drawCard(ctx,38,561,252,124);text(ctx,'PAGO',52,584,9,G,true);
 multiline(ctx,d.payment,52,609,224,12,INK,true,15,2);
 fitted(ctx,d.paymentStatus,52,640,224,9,MUTED);
 roundRect(ctx,52,651,119,21,11,'#e1f5e9');text(ctx,'OPERACIÓN SIMULADA',111.5,665,7.7,G,true,'center');
 const tot=ctx.createLinearGradient(305,561,555,685);tot.addColorStop(0,G);tot.addColorStop(1,'#00705a');
 roundRect(ctx,305,561,252,124,12,tot);
 text(ctx,'RESUMEN',319,584,9,'#e2f5ec',true);
 text(ctx,'Base imponible',319,605,9,'#e0f2ea');text(ctx,euro(q.base),541,605,9,'#fff',true,'right');
 text(ctx,'IVA (21 %)',319,627,9,'#e0f2ea');text(ctx,euro(q.vat),541,627,9,'#fff',true,'right');
 ctx.beginPath();ctx.strokeStyle='#ffffff57';ctx.moveTo(319,639);ctx.lineTo(541,639);ctx.stroke();
 text(ctx,'TOTAL',319,664,11,Y,true);text(ctx,euro(q.total),541,665,18,Y,true,'right');
 // Fiscal disclaimer remains on both modes: both currently generate fake invoices.
 ctx.beginPath();ctx.strokeStyle=BORDER;ctx.moveTo(38,754);ctx.lineTo(557,754);ctx.stroke();
 text(ctx,'DOCUMENTO FICTICIO · SIN VALIDEZ FISCAL',38,774,9,G,true);
 text(ctx,'Datos del emisor y operaciones exclusivamente de demostración.',38,791,8,MUTED);
 text(ctx,'Importes con IVA incluido. No acredita suministro ni pago real.',38,806,8,MUTED);
 if(footerLogo){const w=73;ctx.drawImage(footerLogo,476,766,w,w*footerLogo.height/footerLogo.width)}
}
function binaryPdfFromJpeg(imageUrl,width,height){
 const raw=atob(imageUrl.split(',')[1]);const jpg=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)jpg[i]=raw.charCodeAt(i);
 const enc=new TextEncoder();const chunks=[];let pos=0;const offsets=[0];
 const push=b=>{const arr=typeof b==='string'?enc.encode(b):b;chunks.push(arr);pos+=arr.length};
 const obj=(i,content)=>{offsets[i]=pos;push(i+' 0 obj\n');push(content);push('\nendobj\n')};
 push('%PDF-1.4\n%GASGO\n');
 obj(1,'<< /Type /Catalog /Pages 2 0 R >>');
 obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
 obj(3,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /Im1 4 0 R >> >> /Contents 5 0 R >>');
 offsets[4]=pos;push('4 0 obj\n<< /Type /XObject /Subtype /Image /Width '+width+' /Height '+height+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+jpg.length+' >>\nstream\n');push(jpg);push('\nendstream\nendobj\n');
 const content='q\n595 0 0 842 0 0 cm\n/Im1 Do\nQ\n';
 obj(5,'<< /Length '+enc.encode(content).length+' >>\nstream\n'+content+'endstream');
 const xref=pos;push('xref\n0 6\n0000000000 65535 f \n');for(let i=1;i<=5;i++)push(String(offsets[i]).padStart(10,'0')+' 00000 n \n');
 push('trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF');
 const bytes=new Uint8Array(pos);let at=0;for(const c of chunks){bytes.set(c,at);at+=c.length}return new Blob([bytes],{type:'application/pdf'});
}
async function download(h,f,q){
 const scale=2.5,canvas=document.createElement('canvas');canvas.width=Math.round(595*scale);canvas.height=Math.round(842*scale);
 const ctx=canvas.getContext('2d',{alpha:false});if(!ctx)throw new Error('Este navegador no permite generar la factura PDF');ctx.scale(scale,scale);
 const logos=await Promise.allSettled([loadImage(HEADER_LOGO),loadImage(FOOTER_LOGO)]);
 drawInvoice(ctx,h,f,q,logos[0].status==='fulfilled'?logos[0].value:null,logos[1].status==='fulfilled'?logos[1].value:null);
 const blob=binaryPdfFromJpeg(canvas.toDataURL('image/jpeg',.94),canvas.width,canvas.height);
 const uri=URL.createObjectURL(blob);const a=document.createElement('a');a.href=uri;a.download='GASGO_Factura_'+q.number.replace(/[^\w.-]/g,'_')+'.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(uri),15000);
 return blob;
}
window.GGInvoice={preview,download,fields};
})();
